resources.script:
// #region PREPARSE
/************************************************************
****** Parse timestamp and log headers
****** Extract message field for parsing
****** Parse structured data
************************************************************/
replace(regex="\\\\", with="\\\\\\", as="temp_rawstring")
| parseJson(field="temp_rawstring", prefix="Vendor.", excludeEmpty=true, handleNull=discard)
| parseTimestamp(field="Vendor.time", format=seconds)
// #endregion

// #region METADATA
/************************************************************
****** Static Metadata Definitions
************************************************************/
| Parser.version := "1.0.0"
| Vendor := "microsoft"
| ecs.version := "8.17.0"
| Cps.version := "1.0.0"
| event.module := "edge"
| event.kind := "event"
// #endregion

// #region NORMALIZATION
/************************************************************
****** Parse unstructured data (i.e. message field)
****** Normalize fields to data model
************************************************************/
| event.action := Vendor.event
| event.reference := Vendor.event_detail
| event.reason := Vendor.reason
| device.id := Vendor.device_id
| device.model.name := Vendor.device_name
| url.original := Vendor.url
| parseUrl(Vendor.url, as="url")
| url.domain := rename(url.host)
| url.domain := lower(url.domain)
| user_agent.original := Vendor.user_agent
| host.os.type := Vendor.os_platform
| host.os.version := Vendor.os_version
| user.email := Vendor.profile_user
| user.target.email := Vendor.trigger_user
| user.name := Vendor.device_user
| case {
    user.name = /(?<user.domain>.*?)\\(?<user.name>.*)/;
    *;
 }

| event.action match {
    in(values=["passwordReuseEvent", "passwordBreachEvent"]) =>
        array:append(array="event.category[]", values=["iam"])
        | array:append(array="event.type[]", values=["info"])
    ;
    "passwordChangedEvent" =>
        array:append(array="event.category[]", values=["iam"])
        | array:append(array="event.type[]", values=["change"])
    ;
    in(values=["dangerousDownloadEvent", "sensitiveDataEvent", "unscannedFileEvent"]) =>
        array:append(array="event.category[]", values=["file"])
        | array:append(array="event.type[]", values=["info"])
    ;
    in(values=["badNavigationEvent", "urlFilteringInterstitialEvent"]) =>
        array:append(array="event.category[]", values=["network"])
        | array:append(array="event.type[]", values=["info"])
    ;
    "loginEvent" =>
        array:append(array="event.category[]", values=["authentication"])
        | array:append(array="event.type[]", values=["info"])
    ;
    in(values=["browserExtensionInstallEvent", "browserCrashEvent"]) =>
        array:append(array="event.category[]", values=["process"])
        | array:append(array="event.type[]", values=["info"])
    ;
    * => *;
}
| host.os.type match {
    in(values=["Windows", "win"]) => host.os.type := "windows";
    * => *;
}
// #endregion

// #region POST-NORMALIZATION
/************************************************************
****** Post Normalization
****** Custom parser logic needed after normalization
************************************************************/
| drop(temp_rawstring)
// #endregion
